package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.WorkflowSupport.*;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
final class ClockPurposesAcceptance {
 static void run(WorkflowSupport h) throws Exception {h.account("PurposeReader","reader");String record,other,calendar="Purpose"+id(),api="/api/openservice/operations/clocks";try(var db=h.store.open()){String actor=PlatformFoundationTest.bind(db);record=PlatformFoundationTest.record(db,"incident","Independent service commitments");other=PlatformFoundationTest.record(db,"incident","Another commitment");ServiceClocks.calendar(db,actor,map("name",calendar,"calendar",PlatformFoundationTest.calendar()));db.connection.commit();}
  var start=map("table","incident","record_id",record,"calendar",calendar,"minutes",120,"purpose","response");var response=h.json("POST",api,start,auth("admin"));assertEquals(200,response.statusCode(),html(response));String first=object(parsed(response).get("result")).get("sla_id").toString();assertEquals("response",object(parsed(response).get("result")).get("purpose"));assertEquals(409,h.json("POST",api,start,auth("admin")).statusCode());
  String form="/record/incident/"+record+"/clocks";assertEquals(302,h.protectedForm(form,map("operation","pause","clock_id",first),auth("admin")).statusCode());assertEquals(409,h.json("POST",api,start,auth("admin")).statusCode());
  start.put("purpose","resolution");response=h.json("POST",api,start,auth("admin"));assertEquals(200,response.statusCode());String resolution=object(parsed(response).get("result")).get("sla_id").toString();assertEquals(302,h.protectedForm(form,map("operation","complete","clock_id",first),auth("admin")).statusCode());
  start.put("purpose","response");assertEquals(200,h.json("POST",api,start,auth("admin")).statusCode());start.put("record_id",other);assertEquals(200,h.json("POST",api,start,auth("admin")).statusCode());start.put("record_id",record);
  for(Object bad:List.of("unknown",3,"")){start.put("purpose",bad);assertEquals(400,h.json("POST",api,start,auth("admin")).statusCode());}start.put("purpose","general");assertEquals(200,h.json("POST",api,start,auth("admin")).statusCode());start.remove("purpose");response=h.json("POST",api,start,auth("admin"));assertEquals(200,response.statusCode());assertEquals("general",object(parsed(response).get("result")).get("purpose"));start.put("extra",1);assertEquals(400,h.json("POST",api,start,auth("admin")).statusCode());start.remove("extra");assertEquals(403,h.json("POST",api,start,auth("PurposeReader")).statusCode());assertEquals(400,h.protectedForm(form,map("operation","start","calendar",calendar,"minutes","120","purpose","invalid"),auth("admin")).statusCode());
  assertEquals(400,h.protectedForm(form,map("operation","start","calendar",calendar,"minutes","120","purpose","general","extra","x"),auth("admin")).statusCode());
  new Store(h.environment);try(var db=h.store.open()){assertEquals("completed",db.one("SELECT state FROM os_sla WHERE sla_id=?",first).get("state"));assertEquals("running",db.one("SELECT state FROM os_sla WHERE sla_id=?",resolution).get("state"));assertEquals("resolution",db.one("SELECT purpose FROM os_sla WHERE sla_id=?",resolution).get("purpose"));assertEquals(2,db.count("SELECT COUNT(*) FROM os_sla WHERE record_id=? AND purpose='general'",record));}
  var page=object(parsed(h.get(api+"/"+record+"?table=incident",auth("PurposeReader"))).get("result"));assertTrue(((List<?>)page.get("clocks")).stream().allMatch(row->object(row).containsKey("purpose")));assertTrue(html(h.get(form,auth("PurposeReader"))).contains("resolution"));
 }
}
